import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                pkgs[(name, p['id'])] = p['resolvedVersion']
    return pkgs

bp, ap = extract(b), extract(a)
diff = False
for k in sorted(set(list(bp.keys()) + list(ap.keys()))):
    bv, av = bp.get(k, 'MISSING'), ap.get(k, 'MISSING')
    if bv != av:
        print(f'CHANGED: {k[0]} / {k[1]}: {bv} -> {av}')
        diff = True
if not diff:
    print('All packages resolve identically.')
print(f'Total packages: {len(bp)} baseline, {len(ap)} after')
"

